// MCP tool for batch 53 (1-Nov-2026): packaging dielines.
// The pure core comes from src/tools_core53.js (generated by gen_tools_core.py from tool-gap-2026-10/newtools/fold-core-53.js +
// vendor-geom-51.js) — one source of truth with /tools/dieline-generator/ and the box/matchbox/pillow-box template pages.
// Stateless: no D1/R2, no fetch. Geometry is our own (board-midline rule: crease = inside + t = outside − t); every net is
// fold-checked analytically before it is returned.
import { MGDFold as F } from "./tools_core53.js";

const T = "https://madegooddesigns.com/tools";
const ok = (text, structuredContent) => ({ content: [{ type: "text", text }], structuredContent });
const err = (text) => ({ content: [{ type: "text", text }], isError: true });
const str = (x, max) => (typeof x === "string" ? x : x == null ? "" : String(x)).slice(0, max);
const RO = (title) => ({ title, readOnlyHint: true, destructiveHint: false, openWorldHint: false });
const fence = (lang, s) => "```" + lang + "\n" + String(s).replace(/\n$/, "") + "\n```";
const OUT_CAP = 120 * 1024;
const r2 = (x) => Math.round(x * 100) / 100;
const PAGE = { rte: "dieline-generator", ste: "dieline-generator", rsc: "dieline-generator", cuboid: "box-template", tray: "box-template", lidbase: "box-template", sleeve: "box-template", matchbox: "matchbox-template", pillow: "pillow-box-template" };

export const TOOL_DEFS = [
  {
    name: "make_dieline",
    description: "Use when packaging needs a dieline (flat cut + crease layout): tuck-end carton (reverse/straight), shipping box (FEFCO 0201 RSC), tray, lid + base, sleeve, matchbox or pillow box from L × W × H. Applies board thickness (paper to C-flute) to inside/outside sizes, fold-checks the net, and returns every panel size, flat size, sheets it fits, and a true-size SVG (cut/crease/bleed groups) or DXF (CUT/CREASE/BLEED layers, mm).",
    inputSchema: {
      type: "object",
      properties: {
        structure: { type: "string", enum: ["rte", "ste", "rsc", "tray", "lidbase", "sleeve", "matchbox", "pillow", "cuboid"], description: "rte reverse tuck end (default), ste straight tuck end, rsc shipping box, cuboid glue-tab box. pillow: height = end-curve depth." },
        length: { type: "number" }, width: { type: "number" }, height: { type: "number" },
        unit: { type: "string", enum: ["mm", "in", "cm"], description: "Default mm." },
        basis: { type: "string", enum: ["inside", "outside", "crease"], description: "What the sizes measure (default inside)." },
        board: { type: "string", description: "paper-80, cardstock-65lb, cardstock-110lb, sbs-14, sbs-16 (default; rsc: b-flute), sbs-18, sbs-24, e-flute, b-flute, c-flute, or a thickness in mm." },
        bleed_mm: { type: "number", description: "Default 3; 0 = none." },
        format: { type: "string", enum: ["svg", "dxf", "none"], description: "File returned inline (default svg)." },
      },
      required: ["length", "width", "height"],
    },
    annotations: RO("Packaging dieline"),
  },
];
export const NEXT53 = {
  make_dieline: "Next step: open the page link to add artwork and download a print PDF with spot-colour cut/crease lines and a scale-check square; get_paper_sizes for sheet sizes.",
};

function dieline(a) {
  const s = str(a.structure, 20) || "rte";
  if (!F.STRUCTURES[s]) return err(`Unknown structure "${s}". Use one of: ${Object.keys(F.STRUCTURES).join(", ")}.`);
  const unit = ["mm", "in", "cm"].includes(a.unit) ? a.unit : "mm";
  const L = Number(a.length), W = Number(a.width), H = Number(a.height);
  if (![L, W, H].every((v) => Number.isFinite(v) && v > 0)) return err("length, width and height must be positive numbers.");
  let board = a.board == null ? (s === "rsc" ? "b-flute" : "sbs-16") : str(a.board, 24).trim().toLowerCase();
  const preset = F.CALIPERS.find((c) => c.id === board);
  if (!preset) { const t = parseFloat(board); if (!(t >= 0 && t <= 10)) return err(`Unknown board "${board}". Use ${F.CALIPERS.map((c) => c.id).join(", ")} or a thickness in mm (0–10).`); }
  const basis = ["inside", "outside", "crease"].includes(a.basis) ? a.basis : "inside";
  const bleed = a.bleed_mm == null ? 3 : Math.max(0, Math.min(20, Number(a.bleed_mm) || 0));
  const spec = { structure: s, unit, basis, L, W, H, bleed: F.fromMM(bleed, unit) }; // the core reads bleed in the spec unit
  if (preset) spec.caliper = board; else { spec.caliper = parseFloat(board); spec.caliperUnit = "mm"; }
  const m = F.structure(spec);
  if (!m.ok) return err("Could not build the dieline: " + (m.errors || []).join(" "));
  const v = F.verify(m), sum = F.summary(m), fits = F.sheetsFor(m), u = sum.unit, page = `${T}/${PAGE[s]}/`;
  if (!v.ok) return err("The net failed its fold check; try other sizes. " + (v.details || []).slice(0, 2).join("; "));
  const fmt = ["svg", "dxf", "none"].includes(a.format) ? a.format : "svg";
  const x = (arr) => arr.map(r2).join(" × ");
  const lines = [
    `**${F.describe(m)}**`,
    s === "pillow"
      ? `Board ${preset ? preset.name : r2(sum.dims.caliper) + " mm"}. Each panel ${x(sum.dims.panel.map((v) => F.fromMM(v, u)))} ${u} (width × length) with end curves ${r2(F.fromMM(sum.dims.curve, u))} ${u} deep (capped at 20% of the width).`
      : `Board ${preset ? preset.name : sum.dims.caliper_mm + " mm"}. Inside ${x(sum.dims.inside)} ${u}, crease to crease ${x(sum.dims.crease)} ${u}, outside ${x(sum.dims.outside)} ${u}.`,
    `Flat size ${x(sum.flat)} ${u}${bleed ? ` (+${bleed} mm bleed each side)` : ""}; fits ${fits.length ? fits.join(", ") : "no standard sheet: print as a custom size"}. Cut line ${r2(sum.cut_length)} ${u}, crease line ${r2(sum.crease_length)} ${u}.`,
    "Panels (w × h): " + sum.panels.map((p) => `${p.name} ${r2(p.w)} × ${r2(p.h)}`).join("; ") + ".",
    v.details ? `Fold check passed (${v.details[0]}).` : `Fold check passed (${v.skipped || "geometry checked"}).`,
  ];
  if (sum.lid) lines.push(`Lid (separate net) ${x([sum.lid.L, sum.lid.W, sum.lid.H].map(r2))} mm crease to crease, so it slides over the base.`);
  if (sum.sleeve) lines.push(`Sleeve (separate net) ${x([sum.sleeve.len, sum.sleeve.a, sum.sleeve.b].map(r2))} mm crease to crease (length × width × height), clearing the drawer.`);
  if (m.warnings && m.warnings.length) lines.push("Note: " + m.warnings.join(" "));
  const sc = { structure: s, name: F.STRUCTURES[s].name, ref: F.STRUCTURES[s].ref, unit: u, board_mm: s === "pillow" ? r2(sum.dims.caliper * 1000) / 1000 : sum.dims.caliper_mm, dims: sum.dims, flat: sum.flat, bleed_mm: bleed,
    panels: sum.panels, cut_length_mm: r2(F.toMM(sum.cut_length, u)), crease_length_mm: r2(F.toMM(sum.crease_length, u)), fits_sheets: fits, fold_check: true, page };
  if (fmt !== "none") {
    const file = fmt === "svg" ? F.svg(m) : F.dxf(m);
    if (file.length > OUT_CAP) lines.push(`The ${fmt.toUpperCase()} is ${Math.round(file.length / 1024)} KB: too big to return inline; download it from the page.`);
    else { lines.push(fmt === "svg" ? "True-size SVG (mm; groups cut, crease, bleed):" : "DXF R12 (mm; layers CUT, CREASE, BLEED):", fence(fmt === "svg" ? "svg" : "dxf", file)); sc[fmt] = file; }
  }
  lines.push(`Print PDF with spot-colour lines and artwork: ${page} (print at 100% / actual size).`);
  return ok(lines.join("\n"), sc);
}

const NAMES = new Set(TOOL_DEFS.map((t) => t.name));
export function isTools53Tool(name) { return NAMES.has(name); }
export async function callTools53Tool(name, a) {
  a = a || {};
  try {
    if (name === "make_dieline") return dieline(a);
  } catch (e) {
    return err(`${name} failed: ${str(e && e.message, 300)}`);
  }
  return err("Unknown tool: " + name);
}
